-- Punto delle note del taccuino arrotondato a 2 decimali, circa 1 km, come la base (decisione di Matteo del 28/10/2026).
-- Le note salvate prima con la posizione piena vengono riscritte, con precisione dichiarata di almeno 1000 m.
-- Idempotente: tocca solo le righe non ancora arrotondate. Applicata a runtime da worker/community.js.
UPDATE diary_entries SET payload=json_set(payload,'$.position.latitude',round(json_extract(payload,'$.position.latitude'),2),'$.position.longitude',round(json_extract(payload,'$.position.longitude'),2),'$.position.accuracy',max(coalesce(json_extract(payload,'$.position.accuracy'),0),1000)) WHERE json_valid(payload) AND json_type(payload,'$.position.latitude') IN ('real','integer') AND json_type(payload,'$.position.longitude') IN ('real','integer') AND (json_extract(payload,'$.position.latitude')<>round(json_extract(payload,'$.position.latitude'),2) OR json_extract(payload,'$.position.longitude')<>round(json_extract(payload,'$.position.longitude'),2) OR coalesce(json_extract(payload,'$.position.accuracy'),0)<1000);
